products = [{'name': 'Çay', 'stock': 5}, {'name': 'Simit', 'stock': 0},
            {'name': 'Ayran', 'stock': 3}]

def update_many(query_fn, inc):
    count = 0
    for doc in products:
        if query_fn(doc):
            for field, amount in inc.items():
                doc[field] = doc.get(field, 0) + amount
            count += 1
    return count

print(update_many(lambda d: d['stock'] > 0, {'stock': -1}), products)

